      ?e_elitaLemma elita:HasEmotion ?e_emotion .
      ?e_emotion rdfs:label ?e_emotionLabel .
      GRAPH <http://liita.it/data> {
        ?a_lemma lila:hasPOS ?p_pos .
      }
      ?s_itToSicEntry ontolex:canonicalForm ?a_lemma ;
                   vartrans:translatableAs ?s_sicEntry .
      ?s_sicEntry ontolex:canonicalForm ?s_sicLemma .
      ?s_sicLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
               ontolex:writtenRep ?s_sicWR .
    }
    GROUP BY ?e_emotionLabel ?p_pos
  }
  { SELECT ?e_emotionLabel ?p_pos (COUNT(DISTINCT ?q_parWR) AS ?parCount) WHERE {
      GRAPH <http://liita.it/data> {
        VALUES ?b_lemmaType { lila:Lemma lila:Hypolemma }
        ?b_lemma a ?b_lemmaType .
        ?b_lemma ontolex:writtenRep ?b_wr .
      }
      ?f_elitaLemma ontolex:canonicalForm ?b_lemma .
      ?f_elitaLemma elita:HasEmotion ?f_emotion .
      ?f_emotion rdfs:label ?e_emotionLabel .
      GRAPH <http://liita.it/data> {
        ?b_lemma lila:hasPOS ?p_pos .
      }
      ?q_itToParEntry ontolex:canonicalForm ?b_lemma ;
                   vartrans:translatableAs ?q_parEntry .
      ?q_parEntry ontolex:canonicalForm ?q_parLemma .
      ?q_parLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
               ontolex:writtenRep ?q_parWR .
    }
    GROUP BY ?e_emotionLabel ?p_pos
  }
}

