PREFIX elita: <http://w3id.org/elita/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT (?b_liitaWR AS ?liitaWR) (?s_polarityValue AS ?polarityValue) (?e_emotionLabel AS ?emotionLabel) (?a_definition AS ?definition)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?a_word a ontolex:Word ;
          lexinfo:partOfSpeech [ rdfs:label ?a_posLabel ] ;
          ontolex:sense ?a_sense ;
          ontolex:canonicalForm ?a_form .
    ?a_form ontolex:writtenRep ?a_itLemmaString .
    FILTER(CONTAINS(LCASE(STR(?a_itLemmaString)), LCASE(""))) .
    OPTIONAL { ?a_sense skos:definition ?a_definition . }
    FILTER(str(?a_posLabel) = "verb") .
  }
  ?a_word ontolex:canonicalForm ?b_liitaLemma .
  GRAPH <http://liita.it/data> { ?b_liitaLemma a ?b_liitaLemmaType ; ontolex:writtenRep ?b_liitaWR . FILTER(?b_liitaLemmaType IN (lila:Lemma, lila:Hypolemma)) }
  ?s_sentixLemma ontolex:canonicalForm ?b_liitaLemma ;
               marl:hasPolarity ?s_polarity ;
               marl:hasPolarityValue ?s_polarityValue .
  BIND(STRAFTER(STR(?s_polarity), "#") AS ?s_polarityLabel)
  FILTER(xsd:float(?s_polarityValue) > 0.9)
  ?e_elitaLemma ontolex:canonicalForm ?b_liitaLemma .
  ?e_elitaLemma elita:HasEmotion ?e_emotion .
  ?e_emotion rdfs:label ?e_emotionLabel .
}

