      SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?s_lexicalEntry ontolex:canonicalForm [ ontolex:writtenRep ?s_writtenRep ] .
        ?s_lexicalEntry ontolex:sense ?s_sense .
        FILTER(regex(str(?s_writtenRep), "^(banco|piano|campo|punto)$", "i")) .
      }
    }
    GROUP BY ?s_writtenRep
  }
  { SELECT (MAX(?senseCount) AS ?maxCount) WHERE {
      { SELECT ?s2_writtenRep (COUNT(DISTINCT ?s2_sense) AS ?senseCount) WHERE {
          SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
            ?s2_lexicalEntry ontolex:canonicalForm [ ontolex:writtenRep ?s2_writtenRep ] .
            ?s2_lexicalEntry ontolex:sense ?s2_sense .
            FILTER(regex(str(?s2_writtenRep), "^(banco|piano|campo|punto)$", "i")) .
          }
        }
        GROUP BY ?s2_writtenRep
      }
    }
  }
  FILTER(?senseCount >= ?maxCount)
}

